CREATE TYPE picking_status AS ENUM ('OPEN','IN_PROGRESS','COMPLETED','CANCELLED');
CREATE TABLE picking_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL UNIQUE REFERENCES orders(id), warehouse_id uuid NOT NULL REFERENCES warehouses(id), status picking_status NOT NULL DEFAULT 'OPEN', assigned_to uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE picking_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), picking_session_id uuid NOT NULL REFERENCES picking_sessions(id) ON DELETE CASCADE, order_item_id uuid NOT NULL REFERENCES order_items(id), expected_quantity integer NOT NULL CHECK(expected_quantity>0), picked_quantity integer NOT NULL DEFAULT 0 CHECK(picked_quantity>=0), UNIQUE(picking_session_id,order_item_id));
CREATE TABLE packing_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), picking_session_id uuid NOT NULL UNIQUE REFERENCES picking_sessions(id), packed_by uuid REFERENCES users(id), packed_at timestamptz, verification_code text);
CREATE TABLE packing_scans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), packing_session_id uuid NOT NULL REFERENCES packing_sessions(id) ON DELETE CASCADE, barcode text NOT NULL, scanned_by uuid REFERENCES users(id), scanned_at timestamptz NOT NULL DEFAULT now());
